const fs = require('node:fs');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const [core, evidencePath, fixture, replyPath, resultPath] = process.argv.slice(1);
const hash = value => crypto.createHash('sha256').update(value).digest('hex');
const evidence = JSON.parse(fs.readFileSync(evidencePath));
const body = JSON.parse(fs.readFileSync(fixture)).request;
const source = fs.readFileSync(core);
assert.equal(hash(source), evidence.inputs[core]);
assert.ok(source.length <= 65536);
const {parse, compare} = require('./' + core);
const extract = body => {
  const match = body.match(/^.*\n\[BEFORE CSV\]\n([\s\S]+?)\[AFTER CSV\]\n([\s\S]+?)\[CHANGE BRIEF\]\n([\s\S]+)$/);
  assert.ok(match);
  return match.slice(1);
};
const run = body => {
  const [before, after, brief] = extract(body);
  const findings = compare(parse(before), parse(after), evidence.configuration);
  assert.equal(brief.startsWith('Approve A-01 from 10.00 to 12.00.'), true);
  assert.match(brief, /Confirm the correct C-03 row with the catalogue owner/);
  const approved = brief.includes('Approve B-02 from 20.00 to 25.00.');
  assert.notEqual(approved, brief.includes('Keep B-02 unchanged.'));
  return {findings, decisions: {'A-01':'KEEP 12.00','B-02':approved?'KEEP 25.00':'CORRECT TO 20.00','C-03':'RESOLVE MANUALLY'}};
};
assert.ok(body.includes(evidence.originalBrief));
const original = run(body);
const approved = run(body.replace(evidence.originalBrief, evidence.counterfactualBrief));
assert.deepEqual(original.findings, evidence.findings);
assert.deepEqual(approved.findings, original.findings);
assert.equal(original.decisions['B-02'],'CORRECT TO 20.00');
assert.equal(approved.decisions['B-02'],'KEEP 25.00');
const reply = [
  'Fictional rehearsal / Simulation fictive',
  '',
  'A-01 — Keep 12.00. Your brief approves the change from 10.00 in row 2.',
  'B-02 — Restore 20.00 in row 3. Your brief says to keep the price unchanged, and the updated row contains 25.00.',
  'C-03 — Resolve manually. Ask the catalogue owner which updated row is authoritative, row 4 at 30.00 or row 5 at 35.00, before importing.',
  'Rows are numbered from the CSV header. This review used only the excerpts and instructions supplied. No files were changed or imported. Prepared by autonomous AI agents.',
  '',
  'A-01 — Conserver 12,00. Votre consigne approuve le passage de 10,00 à 12,00 à la ligne 2.',
  'B-02 — Rétablir 20,00 à la ligne 3. Votre consigne maintient le prix initial et la ligne modifiée indique 25,00.',
  'C-03 — Résoudre manuellement. Avant l’importation, demandez au responsable du catalogue quelle ligne modifiée fait foi, la ligne 4 à 30,00 ou la ligne 5 à 35,00.',
  'La numérotation commence à l’en-tête du CSV. La révision se limite aux extraits et aux consignes fournis. Aucun fichier n’a été modifié ni importé. Préparé par des agents IA autonomes.',
  ''
].join('\n');
const sizes = {request_utf8_bytes:Buffer.byteLength(body),reply_utf8_bytes:Buffer.byteLength(reply),reply_characters:[...reply].length};
assert.ok(sizes.request_utf8_bytes < 256 * 1024 && sizes.reply_utf8_bytes < 24000 && reply.length < 32000);
fs.writeFileSync(replyPath, reply);
const result = {coverage:'Public offline rehearsal with fictional data. The program loaded only the checker as service code. Fixture and assertions are public rehearsal inputs.',runtime:process.version,checker:{path:core,bytes:source.length,sha256:hash(source)},sizes,reply_sha256:hash(reply),original,counterfactual_decisions:approved.decisions,checks:{same_findings:true,approval_changes_b02:true,reply_within_documented_limits:true},real_case:['Verify the pinned source path and hash in input_service_sources','Extract the actual plain-text body from the authorized incoming snapshot, confirm the intended sections and mapping, and check total envelope and reply size with host overhead','Verify Node availability, run the case-local command and read its result before composing the reply','Use authorized delivery evidence for the actual reply and separate administrative evidence for acceptance and settlement']};
fs.writeFileSync(resultPath, JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify({sizes,checks:result.checks}));
